package it.penny.api.support;
import it.penny.api.PennyApplication;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.web.context.WebApplicationContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.http.MediaType.APPLICATION_JSON;
@SpringBootTest(classes=PennyApplication.class,properties="penny.trash.cleanup-enabled=false")
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="PENNY_TEST_JDBC_URL",matches=".+")
class SupportIntegrationTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->System.getenv("PENNY_TEST_JDBC_URL")+"?currentSchema=tele_assistance");p.add("spring.datasource.username",()->System.getenv("PENNY_TEST_DB_USER"));p.add("spring.datasource.password",()->System.getenv("PENNY_TEST_DB_PASSWORD"));p.add("spring.flyway.schemas",()->"tele_assistance");}
 @Autowired JdbcTemplate db;@Autowired WebApplicationContext context;@Autowired ObjectMapper json;MockMvc mvc;long user,contact;
 final UsernamePasswordAuthenticationToken admin=new UsernamePasswordAuthenticationToken("support@test.invalid","unused");
 @BeforeEach void setup(){mvc=MockMvcBuilders.webAppContextSetup(context).build();db.execute("TRUNCATE penny_customers,penny_users CASCADE");user=db.queryForObject("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES (?,'Support Admin','unused',false) RETURNING id",Long.class,admin.getName());db.update("INSERT INTO penny_user_roles SELECT ?,id FROM penny_roles WHERE code='ADMIN'",user);db.update("INSERT INTO penny_customers(id,kind,name) VALUES (1,'COMPANY','Uno'),(2,'COMPANY','Due')");contact=db.queryForObject("INSERT INTO penny_customer_contacts(customer_id,full_name) VALUES (1,'Richiedente') RETURNING id",Long.class);}
 long open()throws Exception{var r=mvc.perform(post("/api/support-calls").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("customerId",1,"contactId",contact,"technicianId",user,"description","Errore gestionale")))).andExpect(status().isOk()).andExpect(jsonPath("$.outcome").value("IN_PROGRESS")).andExpect(jsonPath("$.requesterName").value("Richiedente")).andReturn();return json.readTree(r.getResponse().getContentAsString()).get("id").asLong();}
 @Test void createsSingleInterventionAndContactMustBelongToCustomer()throws Exception{long id=open();assertEquals(1L,db.queryForObject("SELECT count(*) FROM penny_customer_records WHERE id=? AND kind='INTERVENTION' AND details->>'interventionType'='REMOTE_SUPPORT'",Long.class,id));mvc.perform(post("/api/support-calls").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("customerId",2,"contactId",contact,"technicianId",user)))).andExpect(status().isBadRequest());db.update("INSERT INTO penny_contact_customers(contact_id,customer_id) VALUES (?,2)",contact);mvc.perform(post("/api/support-calls").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("customerId",2,"contactId",contact,"technicianId",user)))).andExpect(status().isOk());}
 @Test void canCreateContactAtomicallyAndRequiresCustomerWritePermission()throws Exception{mvc.perform(post("/api/support-calls").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("customerId",1,"newContact",Map.of("name","Nuova persona","email","new@example.org"),"technicianId",user)))).andExpect(status().isOk());assertEquals(1L,db.queryForObject("SELECT count(*) FROM penny_contact_customers l JOIN penny_customer_contacts c ON c.id=l.contact_id WHERE c.email='new@example.org' AND l.customer_id=1",Long.class));db.update("INSERT INTO penny_user_permissions(user_id,permission_code,effect) VALUES (?,'CUSTOMERS_WRITE','DENY')",user);mvc.perform(post("/api/support-calls").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("customerId",1,"newContact",Map.of("name","Non creata"),"technicianId",user)))).andExpect(status().isForbidden());assertEquals(0L,db.queryForObject("SELECT count(*) FROM penny_customer_contacts WHERE full_name='Non creata'",Long.class));}
 @Test void closesInEachOutcomeWithEditableTimestampAndComments()throws Exception{for(String outcome:List.of("RESOLVED","PARTIAL","UNRESOLVED","REFUSED")){long id=open();db.update("UPDATE penny_support_calls SET started_at=now()-interval '2 hours' WHERE record_id=?",id);var end=Instant.now().minusSeconds(1800);mvc.perform(post("/api/support-calls/"+id+"/close").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome",outcome,"endedAt",end.toString(),"comment","Conclusione")))).andExpect(status().isOk()).andExpect(jsonPath("$.outcome").value(outcome)).andExpect(jsonPath("$.comments[0].body").value("Conclusione"));assertEquals("COMPLETED",db.queryForObject("SELECT status FROM penny_customer_records WHERE id=?",String.class,id));mvc.perform(post("/api/support-calls/"+id+"/close").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome",outcome,"endedAt",end.toString())))).andExpect(status().isConflict());}}
 @Test void rejectsEndBeforeStartAndFutureWithoutChangingState()throws Exception{long id=open();for(var end:List.of(Instant.now().minusSeconds(3600),Instant.now().plusSeconds(3600))){mvc.perform(post("/api/support-calls/"+id+"/close").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome","RESOLVED","endedAt",end.toString())))).andExpect(status().isBadRequest());}assertEquals("IN_PROGRESS",db.queryForObject("SELECT outcome FROM penny_support_calls WHERE record_id=?",String.class,id));}
 @Test void cancellationRemovesOnlyOpenCalls()throws Exception{long id=open();mvc.perform(delete("/api/support-calls/"+id).principal(admin)).andExpect(status().isOk());mvc.perform(get("/api/support-calls/"+id).principal(admin)).andExpect(status().isNotFound());long closed=open();db.update("UPDATE penny_support_calls SET outcome='RESOLVED',ended_at=now()+interval '1 second' WHERE record_id=?",closed);mvc.perform(delete("/api/support-calls/"+closed).principal(admin)).andExpect(status().isConflict());mvc.perform(get("/api/support-calls/"+closed).principal(admin)).andExpect(status().isOk());}
 @Test void refusalRequiresCommentAndOnlyAssignedTechnicianMayClose()throws Exception{long id=open();mvc.perform(post("/api/support-calls/"+id+"/close").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome","REFUSED","endedAt",Instant.now().toString(),"comment"," ")))).andExpect(status().isBadRequest());long other=db.queryForObject("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES ('other@test.invalid','Other','unused',false) RETURNING id",Long.class);db.update("INSERT INTO penny_user_roles SELECT ?,id FROM penny_roles WHERE code='ADMIN'",other);var next=new UsernamePasswordAuthenticationToken("other@test.invalid","unused");mvc.perform(post("/api/support-calls/"+id+"/close").principal(next).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome","RESOLVED","endedAt",Instant.now().toString())))).andExpect(status().isForbidden());mvc.perform(post("/api/support-calls/"+id+"/reassign").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("technicianId",other)))).andExpect(status().isOk()).andExpect(jsonPath("$.canClose").value(false));assertEquals(other,db.queryForObject("SELECT user_id FROM penny_notifications WHERE support_record_id=?",Long.class,id));mvc.perform(get("/api/support-calls/"+id).principal(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.canEdit").value(false));mvc.perform(post("/api/support-calls/"+id+"/comments").principal(admin).contentType(APPLICATION_JSON).content("{\"body\":\"Non consentito\"}")).andExpect(status().isForbidden());mvc.perform(delete("/api/support-calls/"+id).principal(admin)).andExpect(status().isForbidden());mvc.perform(post("/api/support-calls/"+id+"/reassign").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("technicianId",user)))).andExpect(status().isForbidden());mvc.perform(post("/api/support-calls/"+id+"/comments").principal(next).contentType(APPLICATION_JSON).content("{\"body\":\"Nota assegnatario\"}")).andExpect(status().isOk());mvc.perform(get("/api/support-calls/"+id).principal(next)).andExpect(jsonPath("$.canClose").value(true));long mail=db.queryForObject("INSERT INTO penny_mail_messages(customer_id,message_key,conversation_key,subject,sender,recipients,sent_at,body_text,original_name,original_data,original_kind,saved_by) VALUES (1,'owner-test','owner-thread','Subject','a@example.org','b@example.org',now(),'body','original.eml',decode('ZW1s','base64'),'EML',?) RETURNING id",Long.class,user);mvc.perform(post("/api/mail/"+mail+"/activities").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("recordId",id)))).andExpect(status().isForbidden());mvc.perform(post("/api/mail/"+mail+"/activities").principal(next).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("recordId",id)))).andExpect(status().isOk());mvc.perform(delete("/api/mail/"+mail+"/activities/"+id).principal(admin)).andExpect(status().isForbidden());mvc.perform(post("/api/support-calls/"+id+"/close").principal(next).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome","REFUSED","endedAt",Instant.now().toString(),"comment","Richiesta non accettata")))).andExpect(status().isOk());mvc.perform(post("/api/support-calls/"+id+"/reassign").principal(next).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("technicianId",user)))).andExpect(status().isConflict());mvc.perform(get("/api/support-calls/report").principal(admin).param("year",String.valueOf(Year.now().getValue()))).andExpect(jsonPath("$.monthly["+(LocalDate.now(ZoneId.of("Europe/Rome")).getMonthValue()-1)+"].closedRefused").value(1));}

 @Test void reportSplitsClosedHoursAcrossYearAndExcludesRunningTime()throws Exception{long id=open();db.update("UPDATE penny_support_calls SET started_at='2024-12-31 22:00:00+00',ended_at='2025-01-01 02:00:00+00',outcome='PARTIAL' WHERE record_id=?",id);open();mvc.perform(get("/api/support-calls/report").principal(admin).param("customerId","1").param("year","2024")).andExpect(jsonPath("$.seconds").value(3600)).andExpect(jsonPath("$.monthly[11].partial").value(1));mvc.perform(get("/api/support-calls/report").principal(admin).param("customerId","1").param("year","2025")).andExpect(jsonPath("$.seconds").value(10800)).andExpect(jsonPath("$.technicians[0].seconds").value(10800)).andExpect(jsonPath("$.inProgress").value(1));}
 @Test void ongoingCallsRemainVisibleWhenLookingAtPastYears()throws Exception{open();mvc.perform(get("/api/support-calls").principal(admin).param("year","2024")).andExpect(jsonPath("$.total").value(1));}
 @Test void genericEditorCannotBypassManagedCall()throws Exception{long id=open();mvc.perform(put("/api/customer-records/"+id).principal(admin).contentType(APPLICATION_JSON).content("{\"customerId\":1,\"kind\":\"INTERVENTION\",\"name\":\"Override\",\"status\":\"COMPLETED\",\"details\":{}}")).andExpect(status().isBadRequest());}
 @Test void readOnlyUserCannotCreateCloseOrDelete()throws Exception{long id=open();db.update("INSERT INTO penny_user_permissions(user_id,permission_code,effect) VALUES (?,'ACTIVITIES_WRITE','DENY')",user);mvc.perform(get("/api/support-calls/"+id).principal(admin)).andExpect(status().isOk());mvc.perform(delete("/api/support-calls/"+id).principal(admin)).andExpect(status().isForbidden());mvc.perform(post("/api/support-calls/"+id+"/close").principal(admin).contentType(APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());}
 @Test void daylightSavingUsesElapsedTimeRatherThanWallClock()throws Exception{long id=open();db.update("UPDATE penny_support_calls SET started_at='2025-10-26 00:30:00+00',ended_at='2025-10-26 01:30:00+00',outcome='RESOLVED' WHERE record_id=?",id);mvc.perform(get("/api/support-calls/report").principal(admin).param("year","2025")).andExpect(jsonPath("$.seconds").value(3600));}
 @Test void cancellingRemovesMailAssociationButPreservesOriginalEmail()throws Exception{long id=open();long mail=db.queryForObject("INSERT INTO penny_mail_messages(customer_id,message_key,conversation_key,subject,sender,recipients,sent_at,body_text,original_name,original_data,original_kind,saved_by) VALUES (1,'key','thread','Subject','a@example.org','b@example.org',now(),'body','original.eml',decode('ZW1s','base64'),'EML',?) RETURNING id",Long.class,user);db.update("INSERT INTO penny_mail_record_links(message_id,record_id,customer_id,linked_by) VALUES (?,?,1,?)",mail,id,user);mvc.perform(delete("/api/support-calls/"+id).principal(admin)).andExpect(status().isOk());assertEquals(1L,db.queryForObject("SELECT count(*) FROM penny_mail_messages WHERE id=?",Long.class,mail));assertEquals(0L,db.queryForObject("SELECT count(*) FROM penny_mail_record_links WHERE record_id=?",Long.class,id));}

 @Test void sharedFeedWorksWithoutCustomerOrActivityPermissionsButDoesNotExposeDetails()throws Exception{long id=open();long reader=db.queryForObject("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES ('reader@test.invalid','Reader','unused',false) RETURNING id",Long.class);var auth=new UsernamePasswordAuthenticationToken("reader@test.invalid","unused");mvc.perform(get("/api/support-feed").principal(auth)).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].id").value(id)).andExpect(jsonPath("$.items[0].description").doesNotExist()).andExpect(jsonPath("$.notifications.length()").value(0));mvc.perform(get("/api/support-calls/"+id).principal(auth)).andExpect(status().isForbidden());}
 @Test void assignmentNotificationIsPrivateAndDisappearsWhenClosedOrCancelled()throws Exception{long id=open();mvc.perform(get("/api/support-feed").principal(admin)).andExpect(jsonPath("$.unread").value(1)).andExpect(jsonPath("$.notifications[0].supportId").value(id));long notification=db.queryForObject("SELECT id FROM penny_notifications WHERE support_record_id=?",Long.class,id);db.update("INSERT INTO penny_users(email,full_name,password_hash,must_change_password) VALUES ('other@test.invalid','Other','unused',false)");var other=new UsernamePasswordAuthenticationToken("other@test.invalid","unused");mvc.perform(post("/api/support-feed/notifications/"+notification+"/read").principal(other)).andExpect(status().isNotFound());mvc.perform(post("/api/support-feed/notifications/"+notification+"/read").principal(admin)).andExpect(status().isOk());mvc.perform(get("/api/support-feed").principal(admin)).andExpect(jsonPath("$.unread").value(0));long second=open();mvc.perform(delete("/api/support-calls/"+second).principal(admin)).andExpect(status().isOk());assertEquals(0L,db.queryForObject("SELECT count(*) FROM penny_notifications WHERE support_record_id=?",Long.class,second));db.update("UPDATE penny_support_calls SET started_at=now()-interval '1 hour' WHERE record_id=?",id);mvc.perform(post("/api/support-calls/"+id+"/close").principal(admin).contentType(APPLICATION_JSON).content(json.writeValueAsBytes(Map.of("outcome","RESOLVED","endedAt",Instant.now().toString())))).andExpect(status().isOk());mvc.perform(get("/api/support-feed").principal(admin)).andExpect(jsonPath("$.total").value(0)).andExpect(jsonPath("$.unread").value(0));}
 @Test void dailyListIsNewestFirstAndOngoingBoardIncludesOlderCalls()throws Exception{long older=open(),newer=open();db.update("UPDATE penny_support_calls SET started_at=started_at-interval '2 days' WHERE record_id=?",older);String day=LocalDate.now(ZoneId.of("Europe/Rome")).toString();mvc.perform(get("/api/support-calls").principal(admin).param("year",String.valueOf(LocalDate.now().getYear())).param("day",day)).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].id").value(newer));mvc.perform(get("/api/support-feed").principal(admin)).andExpect(jsonPath("$.total").value(2)).andExpect(jsonPath("$.items[0].id").value(newer));long latest=open();db.update("UPDATE penny_support_calls SET outcome='RESOLVED',ended_at=started_at+interval '1 second' WHERE record_id=?",latest);mvc.perform(get("/api/support-calls").principal(admin).param("year",String.valueOf(LocalDate.now().getYear())).param("day",day)).andExpect(jsonPath("$.items[0].id").value(latest));}

 @Test void closedCallsRemainAvailableInHistoryAndClosureMonthDrivesOutcomeChart()throws Exception{long id=open();db.update("UPDATE penny_support_calls SET started_at='2024-12-31 22:00:00+00',ended_at='2025-01-01 02:00:00+00',outcome='PARTIAL' WHERE record_id=?",id);mvc.perform(get("/api/support-calls").principal(admin).param("year","2026").param("range","ALL")).andExpect(jsonPath("$.items[0].id").value(id));mvc.perform(get("/api/support-calls").principal(admin).param("year","2025").param("range","YEAR").param("month","1")).andExpect(jsonPath("$.total").value(1));mvc.perform(get("/api/support-calls").principal(admin).param("year","2025").param("day","2025-01-01").param("range","DAY")).andExpect(jsonPath("$.total").value(1));mvc.perform(get("/api/support-calls/report").principal(admin).param("year","2025")).andExpect(jsonPath("$.monthly[0].received").value(0)).andExpect(jsonPath("$.monthly[0].closedPartial").value(1));mvc.perform(get("/api/support-calls/report").principal(admin).param("year","2024")).andExpect(jsonPath("$.monthly[11].received").value(1)).andExpect(jsonPath("$.monthly[11].closedPartial").value(0));}

}
